window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[264]={"id":"264","numero":264,"titre":"Insuffisance rénale chronique","objectifs":[{"id":"264-1","rang":"A","rubrique":"Définition","titre":"Connaître les critères définissant la maladie rénale chronique (MRC)","contenu":"<p>La <span class=\"kw-def\">maladie rénale chronique (MRC)</span> se définit par l'existence, depuis <span class=\"kw-chiffre\">plus de 3 mois</span>, d'au moins l'un des marqueurs suivants — l'<span class=\"kw-def\">insuffisance rénale chronique (IRC)</span> n'étant qu'un des critères possibles :</p>\n      <ul>\n        <li><strong><span class=\"kw-ci\">Insuffisance rénale</span></strong> : <span class=\"kw-bio\">DFG</span> <span class=\"kw-chiffre\">&lt; 60 mL/min/1,73 m²</span> (la MRC est alors affirmée même en l'absence de tout autre marqueur).</li>\n        <li><span class=\"kw-bio\">Protéinurie</span> (ou <span class=\"kw-bio\">albuminurie</span>) significative.</li>\n        <li>Anomalie du <span class=\"kw-bio\">sédiment urinaire</span> : <span class=\"kw-clinique\">hématurie</span>, <span class=\"kw-bio\">leucocyturie</span>.</li>\n        <li><span class=\"kw-imagerie\">Anomalies morphologiques</span> des reins ou des voies excrétrices, à condition qu'elles soient cliniquement significatives.</li>\n        <li>Cas particuliers où le diagnostic repose sur des <span class=\"kw-bio\">anomalies ioniques sanguines</span> (certaines tubulopathies).</li>\n      </ul>\n      <p>L'<span class=\"kw-def\">IRC</span> correspond à la <strong>diminution irréversible du <span class=\"kw-bio\">DFG</span></strong> (meilleur indicateur du fonctionnement rénal). Elle résulte soit d'une <span class=\"kw-def\">MRC</span>, soit de la <span class=\"kw-etio\">non-récupération après une agression rénale aiguë</span>.</p>\n      <div class=\"callout callout-info\"><strong>Repère :</strong> entre <span class=\"kw-chiffre\">60</span> et <span class=\"kw-chiffre\">89 mL/min/1,73 m²</span>, l'<span class=\"kw-ci\">insuffisance rénale</span> est dite « légère » et n'est <em>pathologique</em> que s'il existe un marqueur d'atteinte rénale (<span class=\"kw-bio\">protéinurie</span>, <span class=\"kw-bio\">hématurie</span>, <span class=\"kw-bio\">leucocyturie</span>, anomalie morphologique) persistant <span class=\"kw-chiffre\">&gt; 3 mois</span>.</div>","frequence":1},{"id":"264-2","rang":"A","rubrique":"Définition","titre":"Connaître le risque évolutif de l'insuffisance rénale chronique (IRC)","contenu":"<p>Le risque évolutif de l'IRC est double : <strong>progression vers l'<span class=\"kw-def\">insuffisance rénale terminale (IRT)</span></strong> imposant un traitement de suppléance, et <strong>surmortalité <span class=\"kw-alerte\">cardio-vasculaire</span></strong>.</p>\n      <ul>\n        <li><strong>Progression rénale</strong> : aggravation de la <span class=\"kw-def\">MRC</span> jusqu'au <span class=\"kw-def\">stade 5</span> (<span class=\"kw-bio\">DFG</span> <span class=\"kw-chiffre\">&lt; 15</span>), nécessitant <span class=\"kw-ttt\">dialyse</span> ou <span class=\"kw-ttt\">transplantation rénale</span>.</li>\n        <li><strong>Risque cardio-vasculaire</strong> : un patient MRC a un <span class=\"kw-alerte\">risque de mortalité CV supérieur à son risque d'évoluer vers l'IRT</span> — beaucoup de patients meurent d'un accident CV avant d'atteindre la dialyse.</li>\n      </ul>\n      <p>La <strong>vitesse de progression</strong> s'apprécie sur le <span class=\"kw-def\">déclin annuel du DFG</span> (<span class=\"kw-bio\">DFG</span> de l'année précédente − <span class=\"kw-bio\">DFG</span> de l'année actuelle) :</p>\n      <table >\n        <thead><tr><th>Type de déclin</th><th>Vitesse</th></tr></thead>\n        <tbody>\n          <tr><td>Physiologique (après <span class=\"kw-chiffre\">40 ans</span>)</td><td><span class=\"kw-chiffre\">≤ 1 mL/min/an</span></td></tr>\n          <tr><td>Modéré</td><td><span class=\"kw-chiffre\">−1 à −5 mL/min/an</span></td></tr>\n          <tr><td>Rapide</td><td><span class=\"kw-chiffre\">≥ −5 mL/min/an</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-alerte\">Rupture</span> de pente :</strong> toute accélération brutale de la perte de <span class=\"kw-bio\">DFG</span> doit faire rechercher une <span class=\"kw-alerte\">IRA surajoutée</span> (en particulier <span class=\"kw-etio\">fonctionnelle</span>) greffée sur la MRC.</div>","frequence":3},{"id":"264-3","rang":"A","rubrique":"Définition","titre":"Savoir quantifier une protéinurie","contenu":"<p>La <span class=\"kw-bio\">protéinurie</span> est <strong>dépistée</strong> par la <span class=\"kw-bio\">bandelette urinaire (BU)</span>, puis <strong>confirmée et quantifiée</strong> par un dosage. <span class=\"kw-clinique\">Les</span> unités à connaître sont :</p>\n      <ul>\n        <li>Sur <strong>échantillon</strong> : ratio <span class=\"kw-bio\">protéinurie/créatininurie</span> exprimé en <span class=\"kw-chiffre\">g/g</span> de créatininurie (ou <span class=\"kw-chiffre\">mg/mmol</span> de créatininurie).</li>\n        <li>Sur <strong>recueil des <span class=\"kw-chiffre\">24 h</span></strong> : en <span class=\"kw-chiffre\">g/24 h</span>.</li>\n      </ul>\n      <p>La <span class=\"kw-bio\">protéinurie glomérulaire</span> est composée <strong>principalement d'<span class=\"kw-bio\">albumine</span></strong> (<span class=\"kw-chiffre\">≥ 50-60 %</span>), avec ou sans <span class=\"kw-clinique\">syndrome néphrotique</span>. À l'inverse, une <span class=\"kw-bio\">protéinurie</span> <span class=\"kw-def\">tubulaire</span> est de <strong>faible débit</strong> (<span class=\"kw-chiffre\">&lt; 1 g/24 h</span> ou ratio <span class=\"kw-chiffre\">&lt; 1 g/g</span> / <span class=\"kw-chiffre\">&lt; 100 mg/mmol</span>) et de <strong>bas poids moléculaire</strong> (<span class=\"kw-chiffre\">&lt; 50 % d'albumine</span> : β2-microglobuline, RBP).</p>\n      <p>L'<span class=\"kw-bio\">albuminurie</span> sert à <strong>stratifier le risque</strong> (catégories A) et à poser <span class=\"kw-clinique\">les</span> indications de <span class=\"kw-ttt\">néphroprotection</span> :</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Albuminurie</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">A2</span> (<span class=\"kw-bio\">microalbuminurie</span>)</td><td><span class=\"kw-chiffre\">≥ 30 mg/24 h</span> (ou mg/g de créatininurie)</td></tr>\n          <tr><td><span class=\"kw-def\">A3</span> (<span class=\"kw-bio\">protéinurie</span>)</td><td><span class=\"kw-chiffre\">≥ 300 mg/24 h</span> (ou mg/g de créatininurie)</td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"264-4","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l'incidence et la prévalence d'une IRC terminale","contenu":"<p><span class=\"kw-def\">Épidémiologie</span> de l'<span class=\"kw-def\">IRC terminale</span> traitée (France) :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Prévalence</span></strong> : <span class=\"kw-chiffre\">≈ 1 380 / 1 000 000 habitants</span>, répartis en :\n          <ul>\n            <li><span class=\"kw-chiffre\">722</span> traités par <span class=\"kw-ttt\">hémodialyse</span> ;</li>\n            <li><span class=\"kw-chiffre\">46</span> par <span class=\"kw-ttt\">dialyse péritonéale</span> ;</li>\n            <li><span class=\"kw-chiffre\">525</span> porteurs d'une <span class=\"kw-ttt\">greffe rénale</span> fonctionnelle.</li>\n          </ul>\n        </li>\n        <li><strong><span class=\"kw-def\">Incidence</span></strong> : <span class=\"kw-chiffre\">≈ 160 / 1 000 000 habitants / an</span>.</li>\n      </ul>\n      <p>Il existe une <strong>prédominance <span class=\"kw-clinique\">masculine</span></strong> (<span class=\"kw-def\">sex-ratio</span> en faveur des hommes). La majorité des patients prévalents sont donc soit <span class=\"kw-ttt\">dialysés</span>, soit <span class=\"kw-ttt\">transplantés</span>.</p>","frequence":1},{"id":"264-5","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les principales causes d'IRC terminale et les principales causes de néphropathie interstitielle chronique (NIC)","contenu":"<p><strong>Principales causes d'IRT</strong> (par ordre de fréquence décroissante) :</p>\n      <table >\n        <thead><tr><th>Cause</th><th>Part</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Néphropathies vasculaires et hypertensives</span></td><td><span class=\"kw-chiffre\">25 %</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Néphropathies diabétiques</span> (essentiellement <span class=\"kw-etio\">DT2</span>)</td><td><span class=\"kw-chiffre\">22 %</span></td></tr>\n          <tr><td>Néphropathies d'origine indéterminée</td><td><span class=\"kw-chiffre\">16 %</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Glomérulonéphrites chroniques</span></td><td><span class=\"kw-chiffre\">11 %</span></td></tr>\n          <tr><td>Néphropathies diverses</td><td><span class=\"kw-chiffre\">10 %</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Néphropathies héréditaires</span> (surtout <span class=\"kw-etio\">polykystose autosomique dominante</span>)</td><td><span class=\"kw-chiffre\">8 %</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Néphropathies interstitielles chroniques (NIC)</span></td><td><span class=\"kw-chiffre\">&lt; 5 %</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Principales causes de NIC</strong> :</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Détails</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Infections urinaires hautes</span></td><td>Favorisées par une malformation urologique ou des lithiases</td></tr>\n          <tr><td>Causes toxiques</td><td>Analgésiques ; <span class=\"kw-ttt\">AINS</span> ; <span class=\"kw-etio\">plomb</span> ; <span class=\"kw-ttt\">lithium</span></td></tr>\n          <tr><td>Anomalies métaboliques</td><td>Hypokaliémie chronique ; <span class=\"kw-etio\">goutte</span> ; oxalose ; cystinose</td></tr>\n          <tr><td><span class=\"kw-etio\">Maladies kystiques héréditaires</span></td><td>Néphronophtise</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — <span class=\"kw-etio\">Diabète</span> · 224 — <span class=\"kw-etio\">HTA</span> · 266 — Polykystose rénale · 265 — Lithiase urinaire</em></p>","frequence":1},{"id":"264-6","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir identifier les éléments de retentissement clinique de l'IRC chez l'adulte","contenu":"<p>Le retentissement clinique de l'IRC est <strong>multisystémique</strong> et apparaît progressivement avec la baisse du <span class=\"kw-bio\">DFG</span>. <span class=\"kw-clinique\">Les</span> trois fonctions rénales défaillantes (excrétion des <span class=\"kw-etio\">toxines azotées</span>, homéostasie hydro-électrolytique et acido-basique, fonction <span class=\"kw-def\">endocrine</span> : rénine, érythropoïétine, <span class=\"kw-bio\">vitamine D</span> active) expliquent l'ensemble des manifestations :</p>\n      <table >\n        <thead><tr><th>Appareil</th><th>Retentissement clinique</th></tr></thead>\n        <tbody>\n          <tr><td>Cardio-vasculaire</td><td><span class=\"kw-clinique\">HTA</span> (souvent précoce, volo-dépendante) ; <span class=\"kw-clinique\">HVG</span> ; surcharge hydrosodée ; à terme <span class=\"kw-alerte\">péricardite urémique</span></td></tr>\n          <tr><td>Hématologique</td><td><span class=\"kw-clinique\">Anémie</span> normochrome normocytaire arégénérative (pâleur, <span class=\"kw-clinique\">asthénie</span>, <span class=\"kw-clinique\">dyspnée</span>) ; tendance <span class=\"kw-etio\">hémorragique</span> (<span class=\"kw-clinique\">thrombopathie</span>)</td></tr>\n          <tr><td>Osseux / phosphocalcique</td><td><span class=\"kw-clinique\">Douleurs osseuses</span> ; <span class=\"kw-bio\">hypocalcémie</span> ; <span class=\"kw-bio\">hyperphosphorémie</span> ; <span class=\"kw-bio\">hyperparathyroïdie secondaire</span></td></tr>\n          <tr><td>Métabolique</td><td><span class=\"kw-bio\">Acidose métabolique</span> ; <span class=\"kw-bio\">hyperkaliémie</span> ; <span class=\"kw-clinique\">dénutrition</span> protéino-énergétique ; <span class=\"kw-bio\">hyperuricémie</span></td></tr>\n          <tr><td>Digestif</td><td><span class=\"kw-clinique\">Nausées</span>, <span class=\"kw-clinique\">vomissements</span>, <span class=\"kw-clinique\">dégoût pour la viande</span> ; <span class=\"kw-clinique\">gastrite</span>, ulcère</td></tr>\n          <tr><td>Neurologique</td><td>Crampes ; syndrome des jambes sans repos, insomnie ; <span class=\"kw-clinique\">polynévrite</span> et <span class=\"kw-alerte\">encéphalopathie urémiques</span> (stades évolués)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Syndrome urémique</strong> (IRT, <span class=\"kw-bio\">urée &gt; 50 mmol/L</span>) : <span class=\"kw-alerte\">nausées / vomissements</span>, <span class=\"kw-alerte\">dégoût pour la viande</span>, <span class=\"kw-alerte\">prurit</span>, <span class=\"kw-alerte\">polynévrite</span>, <span class=\"kw-alerte\">encéphalopathie</span> et <span class=\"kw-alerte\">péricardite urémique</span> (<span class=\"kw-clinique\">douleur rétrosternale</span>) — ces signes imposent d'envisager le début de la suppléance.</div>","frequence":4},{"id":"264-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les différents stades de la MRC","contenu":"<p>La <span class=\"kw-def\">stadification</span> de la MRC repose sur le <span class=\"kw-bio\">DFG estimé</span> (en mL/min/1,73 m²). <span class=\"kw-clinique\">Les</span> stades 1 et 2 supposent la présence d'un <strong>marqueur d'atteinte rénale depuis <span class=\"kw-chiffre\">≥ 3 mois</span></strong> ; à partir du <span class=\"kw-def\">stade</span> 3, le seul <span class=\"kw-bio\">DFG &lt; 60</span> suffit.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th><span class=\"kw-bio\">DFG</span> (mL/min/1,73 m²)</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">1</span></td><td><span class=\"kw-chiffre\">≥ 90</span></td><td>MRC à fonction rénale normale (marqueur d'atteinte <span class=\"kw-chiffre\">≥ 3 mois</span>)</td></tr>\n          <tr><td><span class=\"kw-def\">2</span></td><td><span class=\"kw-chiffre\">60-89</span></td><td>MRC avec <span class=\"kw-ci\">insuffisance rénale</span> légère (marqueur d'atteinte <span class=\"kw-chiffre\">≥ 3 mois</span>)</td></tr>\n          <tr><td><span class=\"kw-def\">3A</span></td><td><span class=\"kw-chiffre\">45-59</span></td><td><span class=\"kw-ci\">Insuffisance rénale</span> légère à modérée</td></tr>\n          <tr><td><span class=\"kw-def\">3B</span></td><td><span class=\"kw-chiffre\">30-44</span></td><td><span class=\"kw-ci\">Insuffisance rénale</span> modérée à sévère</td></tr>\n          <tr><td><span class=\"kw-def\">4</span></td><td><span class=\"kw-chiffre\">15-29</span></td><td><span class=\"kw-ci\">Insuffisance rénale</span> sévère</td></tr>\n          <tr><td><span class=\"kw-def\">5</span></td><td><span class=\"kw-chiffre\">&lt; 15</span></td><td><span class=\"kw-alerte\">Insuffisance rénale terminale</span> / <span class=\"kw-alerte\">défaillance</span> rénale</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Suffixes :</strong> un patient <span class=\"kw-ttt\">dialysé</span> est classé « <span class=\"kw-def\">stade</span> <span class=\"kw-chiffre\">5D</span> » ; un patient <span class=\"kw-ttt\">transplanté rénal</span> voit son <span class=\"kw-def\">stade</span> <span class=\"kw-def\">suivi</span> de la lettre <span class=\"kw-chiffre\">T</span>.</div>","frequence":3},{"id":"264-8","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir estimer la progression de la MRC","contenu":"<p>La <span class=\"kw-def\">progression</span> de la <span class=\"kw-def\">MRC</span> s'estime sur le <span class=\"kw-def\">déclin annuel du DFG</span> = <span class=\"kw-bio\">DFG</span> de l'année précédente − <span class=\"kw-bio\">DFG</span> de l'année actuelle :</p>\n      <ul>\n        <li><strong>Déclin <span class=\"kw-def\">physiologique</span></strong> (observé après <span class=\"kw-chiffre\">40 ans</span>) : <span class=\"kw-chiffre\">≤ 1 mL/min/an</span>.</li>\n        <li><strong>Déclin <span class=\"kw-def\">modéré</span></strong> : entre <span class=\"kw-chiffre\">−1 et −5 mL/min/an</span>.</li>\n        <li><strong>Déclin <span class=\"kw-def\">rapide</span></strong> : <span class=\"kw-chiffre\">≥ −5 mL/min/an</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\">Devant une <strong>aggravation de la MRC avec <span class=\"kw-alerte\">rupture de pente</span></strong> de perte du <span class=\"kw-bio\">DFG</span>, rechercher systématiquement une <span class=\"kw-alerte\">IRA surajoutée</span> (en particulier <span class=\"kw-etio\">fonctionnelle</span>).</div>","frequence":1},{"id":"264-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les causes d'aggravation de la MRC","contenu":"<p>Cinq grands <strong>facteurs aigus aggravant une IRC</strong> sont à connaître (la plupart sont <span class=\"kw-clinique\">réversibles</span> après correction) :</p>\n      <table >\n        <thead><tr><th>Facteur</th><th>Causes</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Déshydratation extra-cellulaire</span></td><td><span class=\"kw-ttt\">Diurétiques</span> ; <span class=\"kw-clinique\">vomissements</span> ; <span class=\"kw-clinique\">diarrhée</span></td><td>Réversible après <span class=\"kw-ttt\">réduction</span> des <span class=\"kw-ttt\">diurétiques</span> + apport de sel et d'eau</td></tr>\n          <tr><td><span class=\"kw-etio\">Médicaments à effet hémodynamique</span></td><td><span class=\"kw-ttt\">AINS</span> ; <span class=\"kw-ttt\">IEC ++</span> ; <span class=\"kw-ttt\">ARA2</span></td><td>Hypovolémie associée ; sténose des artères rénales ; réversible à l'arrêt</td></tr>\n          <tr><td><span class=\"kw-etio\">Obstacle</span></td><td>Toutes <span class=\"kw-clinique\">les</span> causes d'<span class=\"kw-etio\">obstacle</span> urinaire</td><td>Réversible après levée d'obstacle</td></tr>\n          <tr><td><span class=\"kw-etio\">Produits toxiques</span></td><td><span class=\"kw-ci\">Produits de contraste iodés</span> ; médicaments <span class=\"kw-ci\">néphrotoxiques</span></td><td>Hydratation ++ ; peser <span class=\"kw-clinique\">les</span> indications ; respecter les règles de prescription</td></tr>\n          <tr><td><span class=\"kw-etio\">Pathologie surajoutée</span></td><td><span class=\"kw-clinique\">Pyélonéphrite aiguë</span> ; néphropathie vasculaire surajoutée</td><td>Réversible après traitement spécifique</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 348 — <span class=\"kw-ci\">Insuffisance rénale</span> aiguë - anurie</em></p>","frequence":2},{"id":"264-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les arguments en faveur d'une origine obstructive d'une MRC","contenu":"<p>Toute cause d'<span class=\"kw-etio\">obstacle chronique négligé</span> peut aboutir à une <span class=\"kw-def\">IRC</span> : <strong>plus l'obstacle est levé tardivement, plus la récupération de la <span class=\"kw-bio\">fonction rénale</span> est incomplète</strong>. La recherche d'un <span class=\"kw-etio\">obstacle</span> est donc systématique et précoce.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Argument recherché</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Examen clinique</span></td><td><span class=\"kw-clinique\">Globe vésical</span> ; <span class=\"kw-clinique\">gros rein</span> ; <span class=\"kw-clinique\">touchers pelviens</span> si nécessaire</td></tr>\n          <tr><td><span class=\"kw-imagerie\">Échographie vésicale</span></td><td><span class=\"kw-imagerie\">Résidu post-mictionnel</span></td></tr>\n          <tr><td><span class=\"kw-imagerie\">Échographie des reins et des voies excrétrices</span></td><td><span class=\"kw-radio\">Dilatation des cavités pyélocalicielles</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">Le diagnostic d'<span class=\"kw-def\">origine obstructive</span> repose avant tout sur l'<span class=\"kw-imagerie\">échographie</span> de l'appareil urinaire — examen de débrouillage systématique devant toute <span class=\"kw-def\">MRC</span>.</div>","frequence":1},{"id":"264-11","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les arguments en faveur d'une parenchymateuse d'une MRC","contenu":"<p>Une fois l'obstacle écarté, l'orientation étiologique d'une néphropathie parenchymateuse distingue quatre grands types d'atteinte selon des arguments cliniques et paracliniques :</p>\n      <table >\n        <thead><tr><th>Type d'atteinte</th><th>Arguments cliniques</th><th>Arguments paracliniques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Néphropathie glomérulaire</span></td>\n            <td><span class=\"kw-clinique\">HTA</span> ; <span class=\"kw-clinique\">œdèmes</span> ; ATCD de <span class=\"kw-bio\">protéinurie</span> / <span class=\"kw-clinique\">hématurie</span></td>\n            <td><span class=\"kw-bio\">Protéinurie glomérulaire</span> (<span class=\"kw-chiffre\">&gt; 50 % d'albumine</span>), parfois néphrotique ; <span class=\"kw-bio\">hématurie</span> ± <span class=\"kw-bio\">cylindres hématiques</span> ; reins symétriques, contours réguliers ; atrophie harmonieuse tardive</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Néphropathie tubulo-interstitielle</span></td>\n            <td><span class=\"kw-etio\">HTA</span> absente ou modérée et tardive ; ATCD d'<span class=\"kw-etio\">infections urinaires récidivantes</span>, uropathie, <span class=\"kw-etio\">goutte</span></td>\n            <td><span class=\"kw-bio\">Protéinurie de faible débit</span> (<span class=\"kw-chiffre\">&lt; 1 g/j</span> et/ou <span class=\"kw-chiffre\">&lt; 50 % d'albumine</span>) ; <span class=\"kw-bio\">leucocyturie sans germe</span> ; <span class=\"kw-bio\">cylindres leucocytaires</span> ; atrophie <span class=\"kw-imagerie\">asymétrique</span>, contours bosselés</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Atteinte vasculaire parenchymateuse</span></td>\n            <td><span class=\"kw-etio\">HTA</span> ancienne ; <span class=\"kw-etio\">facteurs de risque cardio-vasculaire</span></td>\n            <td><span class=\"kw-bio\">Protéinurie</span> faible ; <span class=\"kw-imagerie\">reins de taille symétrique</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Atteinte réno-vasculaire</span></td>\n            <td><span class=\"kw-clinique\">HTA résistante</span> à une <span class=\"kw-ttt\">trithérapie</span> ; <span class=\"kw-alerte\">OAP flash</span> ; athéromatose</td>\n            <td><span class=\"kw-bio\">Protéinurie</span> faible ; <span class=\"kw-imagerie\">reins de taille asymétrique</span> (petit rein du côté de la sténose) ; <span class=\"kw-bio\">alcalose hypokaliémique</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Le <span class=\"kw-clinique\">syndrome de NIC</span> associe : <span class=\"kw-bio\">leucocyturie</span> sans germe, absence (ou faible) <span class=\"kw-bio\">hématurie</span>, polyurie, <span class=\"kw-clinique\">natriurèse obligatoire</span> (perte de sel), <span class=\"kw-bio\">protéinurie</span> tubulaire et <span class=\"kw-bio\">acidose tubulaire</span>, avec <span class=\"kw-etio\">HTA</span> tardive. Au <span class=\"kw-def\">stade</span> évolué d'atrophie rénale (fibrose), le diagnostic causal devient souvent impossible.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 261 — Néphropathie glomérulaire</em></p>","frequence":1},{"id":"264-12","rang":"B","rubrique":"Physiopathologie","titre":"Savoir évoquer une néphropathie héréditaire","contenu":"<p>Une <span class=\"kw-etio\">néphropathie héréditaire</span> est évoquée devant des <strong><span class=\"kw-etio\">antécédents familiaux</span> de néphropathie</strong>, à rechercher systématiquement (établir un <span class=\"kw-def\">arbre généalogique</span>). <span class=\"kw-clinique\">Les</span> deux étiologies les plus fréquentes de <span class=\"kw-def\">MRC génétique</span> chez l'adulte sont :</p>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Polykystose rénale autosomique dominante</span></strong> (<span class=\"kw-etio\">PKRAD</span>) +++ — la plus fréquente.</li>\n        <li><strong><span class=\"kw-etio\">Syndrome d'Alport</span></strong> — transmission en général <span class=\"kw-def\">liée à l'X</span>.</li>\n      </ul>\n      <p>L'avis <span class=\"kw-clinique\">néphrologique</span> peut conduire à des <span class=\"kw-bio\">enquêtes génétiques</span> et à des explorations biologiques ciblées (dosage de l'<span class=\"kw-bio\">α-galactosidase</span>, <span class=\"kw-bio\">électrophorèse</span> et <span class=\"kw-bio\">immunofixation des protéines urinaires</span>).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 266 — Polykystose rénale</em></p>","frequence":1},{"id":"264-13","rang":"B","rubrique":"Prise en charge","titre":"Connaître la conduite à tenir en fonction du stade de la MRC","contenu":"<p>La prise en charge est <strong>cumulative</strong> : chaque <span class=\"kw-def\">stade</span> reprend <span class=\"kw-clinique\">les</span> mesures du précédent et ajoute des objectifs propres.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span> (<span class=\"kw-bio\">DFG</span>)</th><th>Conduite à tenir</th></tr></thead>\n        <tbody>\n          <tr><td>1-2 (<span class=\"kw-chiffre\">≥ 60</span>)</td><td>Diagnostic et <span class=\"kw-ttt\">traitement étiologique</span> ; mesures de <span class=\"kw-ttt\">néphroprotection</span> ; vaccinations</td></tr>\n          <tr><td>3A (<span class=\"kw-chiffre\">45-59</span>)</td><td>Idem + diagnostic, prévention et traitement des complications de la MRC et des <span class=\"kw-def\">comorbidités</span></td></tr>\n          <tr><td>3B (<span class=\"kw-chiffre\">30-44</span>)</td><td>Idem + <span class=\"kw-ttt\">préservation du capital veineux</span> ; bilan phospho-calcique ; <span class=\"kw-ttt\">vaccination hépatite B</span></td></tr>\n          <tr><td>4 (<span class=\"kw-chiffre\">15-29</span>)</td><td>Idem + prise en charge <span class=\"kw-bio\">acidose</span>, <span class=\"kw-bio\">hyperkaliémie</span>, <span class=\"kw-clinique\">anémie</span> ; <span class=\"kw-ttt\">information et préparation à la suppléance</span> (création de <span class=\"kw-ttt\">FAV</span>)</td></tr>\n          <tr><td><span class=\"kw-def\">5</span> (<span class=\"kw-chiffre\">&lt; 15</span>)</td><td>Idem + prise en charge <span class=\"kw-clinique\">dénutrition</span> ; <span class=\"kw-ttt\">inscription sur liste de transplantation</span> ; <span class=\"kw-ttt\">dialyse</span> selon la symptomatologie clinico-<span class=\"kw-ttt\">biologique</span></td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Anémie de la MRC (dès le <span class=\"kw-def\">stade</span> 4)</h4>\n      <p>Anémie <strong>arégénérative normochrome normocytaire</strong> (carence en érythropoïétine endogène). Conduite à tenir :</p>\n      <ul>\n        <li><strong>Bilan d'anémie</strong> : <span class=\"kw-bio\">fer</span>, <span class=\"kw-bio\">B9</span>, <span class=\"kw-bio\">B12</span>, <span class=\"kw-clinique\">syndrome <span class=\"kw-etio\">inflammatoire</span></span>.</li>\n        <li><strong>Cible martiale</strong> (plus élevée qu'en population générale) : <span class=\"kw-chiffre\">CST &gt; 20 %</span> et <span class=\"kw-chiffre\">ferritinémie &gt; 200 ng/mL</span>.</li>\n        <li><strong>Si <span class=\"kw-chiffre\">Hb ≤ 10 g/dL</span></strong> : <span class=\"kw-ttt\">érythropoïétine recombinante (époïétine)</span> ou agent dérivé de l'érythropoïétine, en <span class=\"kw-ttt\">SC 1×/semaine ou 1×/mois</span>.</li>\n        <li><strong>Objectif</strong> : <span class=\"kw-chiffre\">Hb entre 10-12 g/dL</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\">Au <span class=\"kw-def\">stade</span> 5, <strong>IRT ≠ dialyse obl<span class=\"kw-chiffre\">iga</span>toire immédiate</strong> : le traitement de suppléance est indiqué en fonction de la symptomatologie clinique et <span class=\"kw-ttt\">biologique</span>, pas du seul chiffre de <span class=\"kw-bio\">DFG</span>.</div>","frequence":2},{"id":"264-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître les facteurs de progression de la MRC","contenu":"<p>Identifier et corriger <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">facteurs de progression</span> est l'objectif central de la <span class=\"kw-ttt\">néphroprotection</span> (en dehors du <span class=\"kw-ttt\">traitement étiologique</span>). Les principaux facteurs <strong>modifiables</strong> sont :</p>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">HTA</span></strong> — facteur majeur de progression.</li>\n        <li><strong><span class=\"kw-bio\">Protéinurie</span> / <span class=\"kw-bio\">albuminurie</span></strong> — plus elle est élevée, plus la <span class=\"kw-def\">progression</span> est rapide.</li>\n        <li><strong><span class=\"kw-etio\">Tabac</span></strong> — favorise la progression de l'<span class=\"kw-def\">IRC</span> (au-delà de ses effets CV) → <span class=\"kw-ttt\">arrêt impératif</span>.</li>\n        <li><strong>Déséquilibre du <span class=\"kw-etio\">diabète</span></strong>.</li>\n        <li><strong>Épisodes d'<span class=\"kw-alerte\">IRA surajoutée</span></strong> et exposition aux <span class=\"kw-ci\">néphrotoxiques</span> (<span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ci\">PDC iodés</span>).</li>\n      </ul>\n      <p>S'y ajoutent des facteurs <strong>non modifiables</strong> (<span class=\"kw-clinique\">sexe masculin</span>, âge, type de néphropathie initiale). La maîtrise des facteurs modifiables ralentit le <span class=\"kw-def\">déclin du DFG</span>.</p>","frequence":2},{"id":"264-15","rang":"A","rubrique":"Prise en charge","titre":"Connaître les objectifs et les moyens de néphroprotection","contenu":"<p>La <span class=\"kw-ttt\">néphroprotection</span> est indiquée <strong>à tout <span class=\"kw-def\">stade</span> de MRC</strong>. Elle vise à ralentir la progression en agissant sur la <span class=\"kw-clinique\">pression artérielle</span>, la <span class=\"kw-bio\">protéinurie</span> et <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">facteurs de risque</span>.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Objectifs thérapeutiques</h4>\n      <table >\n        <thead><tr><th>Cible</th><th>Valeur</th></tr></thead>\n        <tbody>\n          <tr><td>PA — tous <span class=\"kw-clinique\">les</span> cas (sécurité)</td><td><span class=\"kw-chiffre\">PAS &gt; 110 mmHg</span></td></tr>\n          <tr><td>PA — objectif général</td><td><span class=\"kw-chiffre\">&lt; 140/90 mmHg</span></td></tr>\n          <tr><td>PA — si <span class=\"kw-bio\">albuminurie</span> A2/A3 (<span class=\"kw-chiffre\">≥ 30 mg</span>)</td><td><span class=\"kw-chiffre\">&lt; 130/80 mmHg</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Albuminurie</span> cible</td><td><span class=\"kw-chiffre\">&lt; 300 mg/24 h</span></td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Moyens</h4>\n      <ul>\n        <li><strong>Non <span class=\"kw-etio\">médicamenteux</span></strong> : <span class=\"kw-ttt\">restriction sodée</span> <span class=\"kw-chiffre\">&lt; 5 g NaCl/j</span> (<span class=\"kw-chiffre\">85 mmol/j</span>) ; <span class=\"kw-ttt\">arrêt du tabac</span> ; activité physique.</li>\n        <li><strong>Bloqueurs du SRA</strong> : <span class=\"kw-ttt\">IEC</span> ou <span class=\"kw-ttt\">ARA2</span> — diminuent PA et <span class=\"kw-bio\">protéinurie</span> (↓ pression intraglomérulaire). Indiqués dès l'<span class=\"kw-bio\">albuminurie A2</span> (<span class=\"kw-chiffre\">≥ 30 mg</span>) chez le <span class=\"kw-etio\">diabétique</span>, dès l'<span class=\"kw-bio\">albuminurie A3</span> (<span class=\"kw-chiffre\">≥ 300 mg</span>) chez le non-diabétique.</li>\n        <li><strong><span class=\"kw-ttt\">Diurétiques</span></strong> en cas d'<span class=\"kw-etio\">HTA</span> non contrôlée : <span class=\"kw-ttt\">thiazidique</span> si <span class=\"kw-chiffre\">DFG &gt; 30</span>, <span class=\"kw-ttt\">diurétique de l'anse</span> si <span class=\"kw-chiffre\">DFG ≤ 30</span> (seul efficace).</li>\n        <li><strong><span class=\"kw-ttt\">iSGLT2</span> (gliflozines)</strong> si néphropathie diabétique, ou si <span class=\"kw-bio\">albuminurie</span> persistante sous <span class=\"kw-ttt\">IEC</span>/<span class=\"kw-ttt\">ARA2</span> (selon <span class=\"kw-bio\">DFG</span>).</li>\n        <li><span class=\"kw-ttt\">β-bloquant</span> ou <span class=\"kw-ttt\">inhibiteur calcique</span> en cas d'échec d'association.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>PEC des <span class=\"kw-def\">facteurs de risque</span> CV :</strong> le patient IRC est à <span class=\"kw-alerte\">très haut risque cardio-vasculaire</span> — prendre en charge <span class=\"kw-etio\">HTA</span>, <span class=\"kw-etio\">dyslipidémie</span>, <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">tabac</span>, <span class=\"kw-etio\">sédentarité</span>, <span class=\"kw-etio\">obésité</span>. Vaccinations : <span class=\"kw-etio\">grippe</span>, <span class=\"kw-etio\">pneumocoque</span>, COVID-19, <span class=\"kw-ttt\">hépatite B</span> (dès <span class=\"kw-def\">stade</span> 3B si séronégatif). <span class=\"kw-def\">Surveillance</span> : rythme = <span class=\"kw-chiffre\">DFG/10</span> (ex. tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 mois</span> pour un <span class=\"kw-bio\">DFG</span> à 30).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span class=\"kw-etio\">HTA</span> · 223 — <span class=\"kw-etio\">Dyslipidémie</span> · 247 — Diabète</em></p>","frequence":5},{"id":"264-16","rang":"B","rubrique":"Prise en charge","titre":"Connaître les conditions d'introduction, d'utilisation et de surveillance des bloqueurs du Système Rénine Angiotensine","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">IEC</span> et <span class=\"kw-ttt\">ARA2</span> ralentissent la progression de la MRC en diminuant la <span class=\"kw-clinique\">PA</span> et la <span class=\"kw-bio\">protéinurie</span> (baisse de la pression intraglomérulaire).</p>\n      <ul>\n        <li><strong>Introduction</strong> : dès l'<span class=\"kw-bio\">albuminurie A2</span> (<span class=\"kw-chiffre\">≥ 30 mg</span>) chez le <span class=\"kw-etio\">diabétique</span> ; dès l'<span class=\"kw-bio\">albuminurie A3</span> (<span class=\"kw-chiffre\">≥ 300 mg</span>) chez le non-diabétique. Titration progressive jusqu'à la dose maximale autorisée par l'AMM si <span class=\"kw-bio\">protéinurie</span> au-dessus de la cible.</li>\n        <li><strong><span class=\"kw-def\">Surveillance</span></strong> : contrôle de la <span class=\"kw-bio\">créatininémie</span> et de la <span class=\"kw-bio\">kaliémie</span> après chaque modification de dose ; <span class=\"kw-chiffre\">PAS &gt; 110 mmHg</span> à maintenir.</li>\n        <li><strong>Précaution / piège</strong> : une <span class=\"kw-alerte\">dégradation du DFG sous IEC/ARA2</span> en l'absence de <span class=\"kw-clinique\">déshydratation</span> extra-cellulaire doit faire évoquer une <span class=\"kw-etio\">sténose des artères rénales</span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\">En cas de <span class=\"kw-alerte\">déshydratation extra-cellulaire</span> (<span class=\"kw-ttt\">diurétiques</span>, <span class=\"kw-clinique\">vomissements</span>, <span class=\"kw-clinique\">diarrhée</span>) ou d'introduction d'un <span class=\"kw-ttt\">AINS</span>, <span class=\"kw-clinique\">les</span> bloqueurs du SRA majorent le risque d'<span class=\"kw-alerte\">IRA fonctionnelle</span> et d'<span class=\"kw-bio\">hyperkaliémie</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 348 — <span class=\"kw-ci\">Insuffisance rénale</span> aiguë - anurie</em></p>","frequence":1},{"id":"264-17","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de la restriction protidique","contenu":"<p>La <span class=\"kw-ttt\">restriction protidique</span> ralentit la <span class=\"kw-def\">progression</span> de l'<span class=\"kw-def\">insuffisance rénale</span> en diminuant la <span class=\"kw-bio\">charge azotée</span> filtrée.</p>\n      <ul>\n        <li><strong>Indication</strong> : patient avec <span class=\"kw-bio\">DFG</span> <span class=\"kw-chiffre\">&lt; 60 mL/min/1,73 m²</span>.</li>\n        <li><strong><span class=\"kw-bio\">Apport protéique</span></strong> réduit à <span class=\"kw-chiffre\">0,6-0,8 g/kg/j</span>.</li>\n        <li><strong><span class=\"kw-bio\">Apport calorique</span></strong> maintenu suffisant : <span class=\"kw-chiffre\">25-35 kcal/kg/j</span> pour éviter le <span class=\"kw-clinique\">catabolisme</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\">La <span class=\"kw-ttt\">restriction protidique</span> expose au risque de <span class=\"kw-alerte\">dénutrition</span> : elle impose une <span class=\"kw-def\">surveillance</span> nutritionnelle (apport calorique suffisant, marqueurs <span class=\"kw-bio\">albumine</span> / <span class=\"kw-bio\">pré-albumine</span>).</div>","frequence":1},{"id":"264-18","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la dialyse (hémodialyse ou péritonéale)","contenu":"<p>Au <span class=\"kw-def\">stade</span> d'IRT, trois techniques de <span class=\"kw-ttt\">suppléance</span> sont disponibles : <span class=\"kw-ttt\">hémodialyse</span>, <span class=\"kw-ttt\">dialyse péritonéale</span> et <span class=\"kw-ttt\">transplantation rénale</span>. La dialyse repose sur l'épuration du sang au travers d'une <strong>membrane</strong> (synthétique en hémodialyse, péritonéale en dialyse péritonéale).</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/264/schema-hemodialyse.png\" alt=\"Schéma du circuit d'hémodialyse : circulation extracorporelle du sang, dialyseur à membrane semi-perméable, bain de dialyse (dialysat) circulant à contre-courant\" loading=\"lazy\">\n        <figcaption>Circuit d'hémodialyse : le sang circule dans un circuit extracorporel et traverse un dialyseur à membrane semi-perméable, contre un dialysat circulant à contre-courant (transferts diffusifs + ultrafiltration). Source : schéma du Collège de Néphrologie (fiche source EDN item 264).</figcaption>\n      </figure>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Hémodialyse — principe et modalités</h4>\n      <table >\n        <thead><tr><th>Item</th><th>Détails</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Principe</span></td><td><strong>Transferts diffusifs :</strong> selon un gradient de concentration entre sang et <span class=\"kw-bio\">dialysat</span> au travers de la membrane semi-perméable<br><strong>Transferts convectifs :</strong> par <span class=\"kw-def\">ultrafiltration</span> (pression hydrostatique) — soustrait l'eau plasmatique<br><strong>Membrane :</strong> calibrée pour <span class=\"kw-ci\">ne jamais</span> laisser passer l'<span class=\"kw-bio\">albumine</span></td></tr>\n          <tr><td><span class=\"kw-def\">Abords vasculaires</span></td><td><strong><span class=\"kw-ttt\">Fistule artério-veineuse (FAV) :</span></strong> abord de référence ; chirurgien vasculaire ; <span class=\"kw-alerte\">ne se fait pas en urgence</span> (maturation)<br><strong><span class=\"kw-ttt\">Cathéter veineux central :</span></strong> jugulaire interne ou fémorale ; temporaire (<span class=\"kw-alerte\">urgence</span>) ou permanent (obl<span class=\"kw-chiffre\">iga</span>toirement <span class=\"kw-clinique\">tunnélisé</span>)</td></tr>\n          <tr><td><span class=\"kw-def\">Fréquence</span></td><td>Intermittente : séances de <span class=\"kw-chiffre\">4-6 h</span>, <span class=\"kw-chiffre\">3×/semaine</span> (dialysé chronique)<br>Continue : <span class=\"kw-chiffre\">24 h/24</span> plusieurs jours (<span class=\"kw-alerte\">réanimation</span>)</td></tr>\n          <tr><td><span class=\"kw-def\">Objectifs</span></td><td>Atteindre le « poids sec » ; épurer <span class=\"kw-bio\">urée</span> / <span class=\"kw-bio\">créatinine</span> / toxines ; corriger <span class=\"kw-bio\">hyperkaliémie</span>, <span class=\"kw-bio\">acidose</span>, <span class=\"kw-bio\">hypocalcémie</span></td></tr>\n        </tbody>\n      </table>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Dialyse péritonéale</h4>\n      <ul>\n        <li>Utilise le <span class=\"kw-def\">péritoine</span> comme membrane de dialyse (dialysat introduit dans la cavité par un cathéter, échanges diffusifs + ultrafiltration).</li>\n        <li>Épuration <strong>continue</strong> ; modalité manuelle ou automatisée.</li>\n        <li>Avantage : traitement <strong>à domicile</strong>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong><span class=\"kw-ttt\">Transplantation rénale</span> :</strong> meilleure méthode de suppléance (meilleure qualité et espérance de vie, <span class=\"kw-def\">morbidité</span> CV moindre, coût inférieur après la 1ʳᵉ année). Si possible, envisagée dès le <span class=\"kw-def\">stade 5</span>, avant même le début de la dialyse. En France, l'hémodialyse reste la technique la plus utilisée (<span class=\"kw-chiffre\">&gt; 90 %</span>).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 201 — Transplantation d'organe</em></p>","frequence":5},{"id":"264-19","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les complications cardio-vasculaires","contenu":"<p><span class=\"kw-clinique\">Les</span> complications <span class=\"kw-clinique\">cardio-vasculaires</span> dominent le <span class=\"kw-def\">pronostic</span> : <strong><span class=\"kw-alerte\">plus de 50 % des décès</span></strong> des patients IRC sont d'origine vasculaire, et l'<span class=\"kw-clinique\">IDM</span> est <span class=\"kw-chiffre\">3×</span> plus fréquent qu'en population générale.</p>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">HTA</span></strong> — facteur majeur de progression, précoce, souvent <span class=\"kw-def\">volo-dépendante</span> (justifie régime pauvre en sel + <span class=\"kw-ttt\">diurétiques</span>).</li>\n        <li><strong>Lésions artérielles accélérées</strong> : <span class=\"kw-etio\">athérosclérose</span> et <span class=\"kw-etio\">artériosclérose</span>.</li>\n        <li><strong><span class=\"kw-clinique\">HVG</span></strong> — secondaire à l'<span class=\"kw-etio\">HTA</span> et à l'<span class=\"kw-clinique\">anémie</span>.</li>\n        <li><strong>Calcifications</strong> valvulaires et coronariennes.</li>\n        <li><strong>Cardiopathie urémique</strong> — d'étiologie plurifactorielle (ischémie, toxines urémiques).</li>\n      </ul>\n      <p>Aux <span class=\"kw-def\">facteurs de risque</span> communs (<span class=\"kw-etio\">tabac</span>, <span class=\"kw-etio\">HTA</span>, <span class=\"kw-etio\">dyslipidémie</span>, <span class=\"kw-etio\">diabète</span>, âge) s'ajoutent des <strong>FR spécifiques de l'IRC</strong> : troubles phosphocalciques (<span class=\"kw-def\">médiacalcose</span>), <span class=\"kw-bio\">hyperhomocystéinémie</span>, <span class=\"kw-clinique\">anémie</span>, insulino-résistance, toxines urémiques.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span class=\"kw-etio\">HTA</span> · 223 — <span class=\"kw-etio\">Dyslipidémie</span></em></p>","frequence":2},{"id":"264-20","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les caractéristiques des troubles du métabolisme phospho-calcique","contenu":"<p><span class=\"kw-clinique\">Les</span> troubles phospho-calciques sont <strong>précoces</strong>. Leurs traductions biologiques (5) :</p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Anomalie</th></tr></thead>\n        <tbody>\n          <tr><td>Parathyroïdes</td><td><span class=\"kw-bio\">Hyperparathyroïdie secondaire</span>, précoce</td></tr>\n          <tr><td>Vitamine D</td><td><span class=\"kw-bio\">Déficit en vitamine D active</span> (↓ activité 1-α-hydroxylase rénale)</td></tr>\n          <tr><td>Calcium</td><td><span class=\"kw-bio\">Hypocalcémie</span></td></tr>\n          <tr><td>Phosphore</td><td><span class=\"kw-bio\">Hyperphosphorémie</span> (tardive ; maintenue précocement par l'↑ du <span class=\"kw-bio\">FGF23</span>)</td></tr>\n          <tr><td><span class=\"kw-bio\">pH</span></td><td><span class=\"kw-bio\">Acidose métabolique</span> (aggrave <span class=\"kw-clinique\">les</span> lésions osseuses)</td></tr>\n        </tbody>\n      </table>\n      <p>La <span class=\"kw-def\">maladie osseuse rénale</span> associe à divers degrés deux types de lésions :</p>\n      <table >\n        <thead><tr><th></th><th>Ostéomalacie</th><th>Ostéite fibreuse</th></tr></thead>\n        <tbody>\n          <tr><td>Mécanisme</td><td><span class=\"kw-def\">↓ formation osseuse</span></td><td><span class=\"kw-def\">Destruction osseuse accélérée</span></td></tr>\n          <tr><td>Cause</td><td><span class=\"kw-etio\">Déficit en vitamine D</span></td><td><span class=\"kw-etio\">Hyperparathyroïdie</span></td></tr>\n          <tr><td>Radio</td><td><span class=\"kw-radio\">Stries de Looser-Milkman</span> ; déminéralisation « cotonneuse »</td><td><span class=\"kw-radio\">Résorption des extrémités</span> (phalanges, clavicules) ; lacunes</td></tr>\n          <tr><td>Biologie</td><td>↓ <span class=\"kw-bio\">calcitriol</span></td><td>↑ <span class=\"kw-bio\">PTH</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Traitement :</strong> <span class=\"kw-bio\">calcémie</span> normale, <span class=\"kw-bio\">phosphatémie &lt; 1,5 mmol/L</span>, <span class=\"kw-bio\">PTH</span> normalisée. Moyens : <span class=\"kw-ttt\">vitamine D native</span> si carence, apports calciques <span class=\"kw-chiffre\">1-2,5 g/j</span>, restriction du phosphore + <span class=\"kw-ttt\">complexants du phosphore</span> (carbonate/acétate de calcium puis chélateurs sans calcium). <span class=\"kw-ci\">Gels d'aluminium proscrits</span> (toxicité neurologique et osseuse).</div>","frequence":2},{"id":"264-21","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les mécanismes de l'acidose métabolique au cours de l'IRC et sa prévention","contenu":"<p>L'<span class=\"kw-bio\">acidose métabolique</span> de l'<span class=\"kw-def\">IRC</span> est secondaire à un <span class=\"kw-def\">défaut d'élimination rénale de la charge d'acide</span>. Elle est généralement modérée (sauf certaines <span class=\"kw-etio\">tubulopathies</span>) :</p>\n      <ul>\n        <li><strong>Diminution des <span class=\"kw-bio\">bicarbonates</span></strong> ;</li>\n        <li>Augmentation faible du <span class=\"kw-bio\">trou anionique</span> ;</li>\n        <li><span class=\"kw-bio\">pH</span> conservé jusqu'à un <span class=\"kw-def\">stade</span> évolué de la <span class=\"kw-def\">MRC</span>.</li>\n      </ul>\n      <p><strong>Prévention / traitement</strong> :</p>\n      <ul>\n        <li>Objectif : <span class=\"kw-bio\">bicarbonatémie</span> <span class=\"kw-chiffre\">&gt; 23 mmol/L</span>.</li>\n        <li><span class=\"kw-ttt\">Bicarbonate de sodium</span> (gélules de <span class=\"kw-ttt\">NaHCO₃</span> à <span class=\"kw-chiffre\">0,5-1 g</span>, soit <span class=\"kw-chiffre\">3-6 g/j</span>) ;</li>\n        <li>ou <span class=\"kw-ttt\">eau de Vichy</span> (<span class=\"kw-chiffre\">0,5-1 L/j</span>).</li>\n      </ul>","frequence":1},{"id":"264-22","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les conséquences de l'acidose métabolique","contenu":"<p><span class=\"kw-clinique\">Les</span> conséquences de l'<span class=\"kw-bio\">acidose métabolique</span> chronique au cours de l'<span class=\"kw-def\">IRC</span> sont au nombre de trois :</p>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Catabolisme protéique musculaire</span> excessif</strong> — contribue à la <span class=\"kw-clinique\">dénutrition</span>.</li>\n        <li><strong>Aggravation des lésions d'<span class=\"kw-def\">ostéodystrophie rénale</span></strong>.</li>\n        <li><strong>Majoration du risque d'<span class=\"kw-alerte\">hyperkaliémie</span></strong>.</li>\n      </ul>\n      <p>Ces conséquences justifient la correction de l'<span class=\"kw-bio\">acidose</span> (objectif <span class=\"kw-bio\">bicarbonatémie</span> <span class=\"kw-chiffre\">&gt; 23 mmol/L</span>), qui croise la prise en charge du <span class=\"kw-def\">métabolisme phospho-calcique</span> et de la <span class=\"kw-bio\">kaliémie</span>.</p>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>IRA surajoutée sur MRC <span class=\"q\">— <span class=\"kw-alerte\">rupture</span> de pente du <span class=\"kw-bio\">DFG</span></span></strong></p><p>identifier et corriger la cause sans délai (le plus souvent <span class=\"kw-clinique\">réversible</span>) : <span class=\"kw-ttt\">suspendre les néphrotoxiques</span>, réhydrater, lever l'obstacle</p><ul><li><span class=\"kw-etio\">Déshydratation extra-cellulaire</span> : <span class=\"kw-ttt\">diurétiques</span>, <span class=\"kw-clinique\">vomissements</span>, <span class=\"kw-clinique\">diarrhée</span></li><li><span class=\"kw-etio\">Médicaments à effet hémodynamique</span> : <span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">IEC</span>, <span class=\"kw-ttt\">ARA2</span></li><li><span class=\"kw-etio\">Obstacle</span> sur <span class=\"kw-clinique\">les</span> voies urinaires</li><li><span class=\"kw-ci\">Produits de contraste iodés</span> et autres <span class=\"kw-ci\">néphrotoxiques</span></li><li><span class=\"kw-etio\">Pathologie surajoutée</span> : <span class=\"kw-clinique\">pyélonéphrite aiguë</span>, néphropathie vasculaire</li></ul><p><strong>Mise en route de la suppléance en <span class=\"kw-alerte\">urgence</span></strong></p><p>abord en <span class=\"kw-alerte\">urgence</span> = <span class=\"kw-ttt\">cathéter veineux central</span> temporaire (<span class=\"kw-clinique\">jugulaire interne</span> ou <span class=\"kw-clinique\">fémorale</span>) — la <span class=\"kw-ttt\">FAV</span> <span class=\"kw-ci\">ne se fait pas en urgence</span> (maturation)</p><ul><li><span class=\"kw-alerte\">Syndrome urémique</span> (<span class=\"kw-bio\">urée &gt; 50 mmol/L</span>) → impose d'envisager le début de la <span class=\"kw-ttt\">suppléance</span></li><li>Anomalies corrigées par l'<span class=\"kw-ttt\">épuration extra-rénale</span> : <span class=\"kw-alerte\">hyperkaliémie</span>, <span class=\"kw-bio\">acidose métabolique</span>, <span class=\"kw-alerte\">surcharge hydrosodée</span></li></ul>","hospit":"<p><strong>Avis néphrologique spécialisé</strong></p><ul><li>Indication d'une <span class=\"kw-ttt\">biopsie rénale</span> et d'explorations complémentaires (tubulopathie, lithiase, kystes, dysplasie)</li><li><span class=\"kw-bio\">Enquête génétique</span> et examens ciblés (<span class=\"kw-bio\">α-galactosidase</span>, <span class=\"kw-bio\">électrophorèse / immunofixation des protéines urinaires</span>) si néphropathie <span class=\"kw-etio\">héréditaire</span></li></ul><p><strong>Préparation à la suppléance <span class=\"q\">— anticipée, échelonnée par <span class=\"kw-def\">stade</span></span></strong></p><ul><li><span class=\"kw-def\">Stade 3B</span> (<span class=\"kw-chiffre\">30-44</span>) : <span class=\"kw-ttt\">préservation du capital veineux</span> ; <span class=\"kw-ttt\">vaccination hépatite B</span></li><li><span class=\"kw-def\">Stade 4</span> (<span class=\"kw-chiffre\">15-29</span>) : <span class=\"kw-ttt\">information</span> et création d'une <span class=\"kw-ttt\">fistule artério-veineuse (FAV)</span></li><li><span class=\"kw-def\">Stade 5</span> (<span class=\"kw-chiffre\">&lt; 15</span>) : <span class=\"kw-ttt\">inscription sur liste de transplantation</span> dès que possible</li></ul><p><strong>Modalités d'épuration</strong></p><ul><li><span class=\"kw-ttt\">Hémodialyse</span> : en centre, en unité de dialyse médicalisée, en autodialyse ou à domicile</li><li><span class=\"kw-ttt\">Dialyse péritonéale</span> : traitement à domicile</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Rupture de pente</span> du <span class=\"kw-bio\">DFG</span> (déclin <span class=\"kw-chiffre\">≥ −5 mL/min/an</span>) → rechercher une <span class=\"kw-alerte\">IRA surajoutée</span>, surtout <span class=\"kw-etio\">fonctionnelle</span></li><li><span class=\"kw-alerte\">Syndrome urémique</span> (<span class=\"kw-bio\">urée &gt; 50 mmol/L</span>) : <span class=\"kw-alerte\">nausées/vomissements</span>, <span class=\"kw-clinique\">dégoût pour la viande</span>, <span class=\"kw-clinique\">prurit</span>, <span class=\"kw-alerte\">polynévrite</span>, <span class=\"kw-alerte\">encéphalopathie</span>, <span class=\"kw-alerte\">péricardite urémique</span></li><li><span class=\"kw-alerte\">Dégradation du DFG sous IEC/ARA2</span> sans <span class=\"kw-clinique\">déshydratation</span> extra-cellulaire → évoquer une <span class=\"kw-etio\">sténose des artères rénales</span></li><li><span class=\"kw-clinique\">HTA résistante</span> à une <span class=\"kw-ttt\">trithérapie</span> + <span class=\"kw-alerte\">OAP flash</span> → atteinte <span class=\"kw-etio\">réno-vasculaire</span></li><li><span class=\"kw-alerte\">Hyperkaliémie</span> (majorée par l'<span class=\"kw-bio\">acidose</span>, <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">IEC/ARA2</span> et les <span class=\"kw-ttt\">AINS</span>)</li></ul>","principes":"<p>Deux objectifs gouvernent toute la PEC : <span class=\"kw-ttt\">néphroprotection</span> (ralentir le déclin du <span class=\"kw-bio\">DFG</span>) et prévention du <span class=\"kw-alerte\">risque cardio-vasculaire</span>, très élevé. La prise en charge est <strong>cumulative</strong> : chaque <span class=\"kw-def\">stade</span> reprend <span class=\"kw-clinique\">les</span> mesures du précédent et en ajoute.</p><p><strong>Néphroprotection <span class=\"q\">— indiquée à tout <span class=\"kw-def\">stade</span></span></strong></p><p>cible d'<span class=\"kw-bio\">albuminurie</span> <span class=\"kw-chiffre\">&lt; 300 mg/24 h</span> ; surveiller <span class=\"kw-bio\">créatininémie</span> et <span class=\"kw-bio\">kaliémie</span> après chaque modification</p><ul><li>Cibles de PA : <span class=\"kw-chiffre\">&lt; 140/90 mmHg</span>, ou <span class=\"kw-chiffre\">&lt; 130/80 mmHg</span> si <span class=\"kw-bio\">albuminurie A2/A3</span> ; toujours <span class=\"kw-chiffre\">PAS &gt; 110 mmHg</span></li><li><span class=\"kw-ttt\">IEC</span> ou <span class=\"kw-ttt\">ARA2</span> : dès <span class=\"kw-bio\">albuminurie A2</span> (<span class=\"kw-chiffre\">≥ 30 mg</span>) chez le <span class=\"kw-etio\">diabétique</span>, dès <span class=\"kw-bio\">albuminurie A3</span> (<span class=\"kw-chiffre\">≥ 300 mg</span>) chez le non-diabétique</li><li><span class=\"kw-ttt\">Restriction sodée</span> <span class=\"kw-chiffre\">&lt; 5 g NaCl/j</span> ; <span class=\"kw-ttt\">arrêt du tabac</span> impératif</li><li><span class=\"kw-ttt\">iSGLT2</span> (gliflozines) si néphropathie diabétique ou <span class=\"kw-bio\">albuminurie</span> persistante sous <span class=\"kw-ttt\">IEC</span>/<span class=\"kw-ttt\">ARA2</span></li><li><span class=\"kw-ttt\">Diurétique thiazidique</span> si <span class=\"kw-chiffre\">DFG &gt; 30</span>, <span class=\"kw-ttt\">diurétique de l'anse</span> si <span class=\"kw-chiffre\">DFG ≤ 30</span> (seul efficace)</li></ul><p><strong>Restriction protidique <span class=\"q\">— si <span class=\"kw-bio\">DFG</span> &lt; 60</span></strong></p><p><span class=\"kw-def\">surveillance</span> nutritionnelle (<span class=\"kw-bio\">albumine</span>, <span class=\"kw-bio\">pré-albumine</span>) — risque de <span class=\"kw-alerte\">dénutrition</span></p><ul><li><span class=\"kw-bio\">Apport protéique</span> réduit à <span class=\"kw-chiffre\">0,6-0,8 g/kg/j</span></li><li><span class=\"kw-bio\">Apport calorique</span> maintenu à <span class=\"kw-chiffre\">25-35 kcal/kg/j</span> pour éviter le <span class=\"kw-clinique\">catabolisme</span></li></ul><p><strong>Anémie <span class=\"q\">— arégénérative, dès le <span class=\"kw-def\">stade</span> 4</span></strong></p><p>objectif <span class=\"kw-chiffre\">Hb 10-12 g/dL</span></p><ul><li>Bilan : <span class=\"kw-bio\">fer</span>, <span class=\"kw-bio\">B9</span>, <span class=\"kw-bio\">B12</span>, syndrome <span class=\"kw-bio\">inflammatoire</span> ; cibles martiales <span class=\"kw-chiffre\">CST &gt; 20 %</span>, <span class=\"kw-chiffre\">ferritine &gt; 200 ng/mL</span></li><li>Si <span class=\"kw-chiffre\">Hb ≤ 10 g/dL</span> : <span class=\"kw-ttt\">érythropoïétine recombinante</span> en <span class=\"kw-ttt\">SC</span> (1×/semaine ou 1×/mois)</li></ul><p><strong>Troubles phospho-calciques</strong></p><p><span class=\"kw-ci\">gels d'aluminium proscrits</span> (toxicité neurologique et osseuse)</p><ul><li>Objectifs : <span class=\"kw-bio\">calcémie</span> normale, <span class=\"kw-bio\">phosphatémie &lt; 1,5 mmol/L</span>, <span class=\"kw-bio\">PTH</span> contrôlée</li><li><span class=\"kw-ttt\">Vitamine D native</span> si carence ; apports calciques <span class=\"kw-chiffre\">1-2,5 g/j</span> ; <span class=\"kw-ttt\">complexants du phosphore</span></li></ul><p><strong>Acidose métabolique &amp; hyperkaliémie</strong></p><ul><li>Acidose — objectif <span class=\"kw-bio\">bicarbonatémie &gt; 23 mmol/L</span> : <span class=\"kw-ttt\">bicarbonate de sodium</span> (<span class=\"kw-chiffre\">3-6 g/j</span>) ou <span class=\"kw-ttt\">eau de Vichy</span></li><li>Hyperkaliémie : correction de l'<span class=\"kw-bio\">acidose</span>, limitation des apports en <span class=\"kw-bio\">K+</span>, <span class=\"kw-ttt\">résines échangeuses d'ions</span></li></ul><p><strong>Risque cardio-vasculaire &amp; vaccinations</strong></p><ul><li>Patient à <span class=\"kw-alerte\">très haut risque cardio-vasculaire</span> : PEC <span class=\"kw-etio\">HTA</span>, <span class=\"kw-etio\">dyslipidémie</span>, <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">tabac</span>, <span class=\"kw-etio\">sédentarité</span>, <span class=\"kw-etio\">obésité</span></li><li>Vaccinations : <span class=\"kw-ttt\">grippe</span>, <span class=\"kw-ttt\">pneumocoque</span>, <span class=\"kw-ttt\">COVID-19</span>, <span class=\"kw-ttt\">hépatite B</span> (dès <span class=\"kw-def\">stade</span> 3B si séronégatif)</li></ul><p><strong>Suppléance <span class=\"q\">— <span class=\"kw-def\">stade</span> 5 / IRT</span></strong></p><p>IRT ≠ dialyse immédiate : la suppléance est indiquée selon la <span class=\"kw-clinique\">symptomatologie</span> clinico-<span class=\"kw-ttt\">biologique</span>, pas le seul chiffre de <span class=\"kw-bio\">DFG</span></p><ul><li><span class=\"kw-ttt\">Transplantation rénale</span> : meilleure méthode, envisagée dès le <span class=\"kw-def\">stade 5</span>, si possible avant la dialyse</li><li><span class=\"kw-ttt\">Hémodialyse</span> (technique la plus utilisée en France, <span class=\"kw-chiffre\">&gt; 90 %</span>) : séances de <span class=\"kw-chiffre\">4-6 h</span>, <span class=\"kw-chiffre\">3×/semaine</span>, via <span class=\"kw-ttt\">FAV</span></li><li><span class=\"kw-ttt\">Dialyse péritonéale</span> : épuration continue, à domicile</li></ul>","suivi":"<p><strong>Rythme :</strong> <span class=\"kw-def\">surveillance</span> de l'IRC = <span class=\"kw-bio\">DFG</span>/10 (ex. tous <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">3 mois</span> pour un <span class=\"kw-bio\">DFG à 30</span>).<br><strong><span class=\"kw-def\">Dépistage</span> :</strong> annuel chez les sujets à risque (<span class=\"kw-chiffre\">âge &gt; 60 ans</span>, <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">HTA</span>, <span class=\"kw-etio\">obésité</span>, ATCD familiaux de néphropathie) par <span class=\"kw-bio\">DFG estimé</span> + <span class=\"kw-bio\">albuminurie</span> sur échantillon.<br><strong>Sous <span class=\"kw-ttt\">IEC</span>/<span class=\"kw-ttt\">ARA2</span> :</strong> contrôle de la <span class=\"kw-bio\">créatininémie</span> et de la <span class=\"kw-bio\">kaliémie</span> après chaque modification de dose ; maintenir <span class=\"kw-chiffre\">PAS &gt; 110 mmHg</span>.<br><strong>Objectifs biologiques :</strong> <span class=\"kw-bio\">bicarbonatémie &gt; 23 mmol/L</span>, <span class=\"kw-chiffre\">Hb 10-12 g/dL</span>, <span class=\"kw-bio\">phosphatémie &lt; 1,5 mmol/L</span>, <span class=\"kw-bio\">albuminurie &lt; 300 mg/24 h</span>.</p>"},"liensGlobaux":[{"href":"https://manuel4.cuen.fr/spip.php?rubrique18","label":"CUEN — Manuel de Néphrologie (IRC)"}],"cards":[{"i":"15d1148ad890","n":264,"o":"264-20","u":"Suivi et/ou pronostic","t":"Connaître les caractéristiques des troubles du métabolisme phospho-calcique","q":"Quels sont les objectifs et les moyens thérapeutiques pour la prise en charge des troubles phospho-calciques dans l'insuffisance rénale chronique ?","a":"Les objectifs thérapeutiques sont une <strong>calcémie normale</strong>, une <strong>phosphatémie inférieure à 1,5 mmol/L</strong> et une <strong>PTH normalisée</strong>. Les moyens comprennent :<ul><li>Supplémentation en <strong>vitamine D native</strong> en cas de carence.</li><li><strong>Apports calciques de 1-2,5 g/jour</strong>.</li><li><strong>Restriction du phosphore alimentaire</strong> et utilisation de <strong>complexants du phosphore</strong> (carbontate ou acétate de calcium puis chélateurs sans calcium).</li><li>Les gels d'aluminium sont <strong>proscrits</strong> en raison de leur toxicité neurologique et osseuse.</li></ul>"},{"i":"7eba6b4becd0","n":264,"o":"264-20","u":"Suivi et/ou pronostic","t":"Connaître les caractéristiques des troubles du métabolisme phospho-calcique","q":"Quelles sont les principales anomalies biologiques du métabolisme phospho-calcique observées au cours de l'insuffisance rénale chronique ?","a":"<ul><li><strong>Hyperparathyroïdie secondaire</strong> : précoce, due à la résistance des glandes parathyroïdes et à la carence en vitamine D.</li><li><strong>Déficit en vitamine D active</strong> (calcitriol) : par diminution de l'activité de la 1-alpha-hydroxylase rénale.</li><li><strong>Hypocalcémie</strong>.</li><li><strong>Hyperphosphorémie</strong> : plus tardive, mais avec maintien précoce par l'augmentation du FGF23.</li><li><strong>Acidose métabolique</strong> : qui aggrave les lésions osseuses.</li></ul>"},{"i":"bccbf65fab6e","n":264,"o":"264-20","u":"Suivi et/ou pronostic","t":"Connaître les caractéristiques des troubles du métabolisme phospho-calcique","q":"Quelles sont les deux principales composantes de la maladie osseuse rénale chez l'insuffisant rénal chronique, et leurs mécanismes et causes respectifs ?","a":"<ul><li><strong>Ostéomalacie</strong> : cause une diminution de la formation osseuse, secondaire à un déficit en vitamine D.</li><li><strong>Ostéite fibreuse</strong> : entraîne une destruction osseuse accélérée, secondaire à l'hyperparathyroïdie.</li></ul>"}]};